void invert(inout vec2 p, inout float n, inout bool fund, vec2 c, vec2 r) {
    // Inversion in an ellipse
    vec2 q = p - c;
    vec2 qq = q * q, rr = r * r;
    if (rr.y * qq.x + rr.x * qq.y < rr.x * rr.y) {
        p = c + q * rr.x * rr.y / dot(qq, rr.yx);
        n ++;
        fund = false;
    }
}

float a, b;

vec4 getColor(vec2 p) {
    // Gets the color at a given pixel coordinate
    p = 1.5 * (2. * p - iResolution.xy) / iResolution.y;
    float n = 0.;
    bool fund;
    for (int i = 0; i < 50; i ++) {
        fund = true;

        invert(p, n, fund, vec2(a + b) * .5, vec2(a, b));
        invert(p, n, fund, vec2(-a - b, a + b) * .5, vec2(b, a));
        invert(p, n, fund, vec2(-a - b) * .5, vec2(a, b));
        invert(p, n, fund, vec2(a + b, -a - b) * .5, vec2(b, a));

        if (fund) break;
    }
    return vec4(mod(n, 2.));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float t = .1 * iTime;
    a = abs(cos(t));
    b = abs(sin(t));

    // Multisampling
    fragColor = getColor(fragCoord);
    fragColor += getColor(fragCoord + vec2(.5, 0.));
    fragColor += getColor(fragCoord + vec2(-.5, 0.));
    fragColor += getColor(fragCoord + vec2(0., .5));
    fragColor += getColor(fragCoord + vec2(0., -.5));
    fragColor += getColor(fragCoord + vec2(.5, .5));
    fragColor += getColor(fragCoord + vec2(-.5, .5));
    fragColor += getColor(fragCoord + vec2(.5, .5));
    fragColor += getColor(fragCoord + vec2(.5, -.5));
    fragColor *= .1111;
}
